// ---------- API ----------
async function api(fn,args){
  if(window.__MOCK) return window.__MOCK(fn,args||{});
  let res;
  try{ res=await fetch(CFG.url+'/rest/v1/rpc/'+fn,{method:'POST',headers:{'apikey':CFG.key,'Authorization':'Bearer '+CFG.key,'Content-Type':'application/json'},body:JSON.stringify(args||{})}); }
  catch(e){ throw new Error('OFFLINE'); }
  let j=null; try{ j=await res.json(); }catch(e){}
  if(!res.ok){ const m=(j&&(j.message||j.error_description||j.error))||('Server error '+res.status); if(/^AUTH/.test(m)){ signOut(true); } throw new Error(String(m).replace(/^AUTH: /,'')); }
  return j;
}
const call=(fn,args)=>api(fn,Object.assign({p_token:S.token},args||{}));
function toast(m,err){ const o=$('.toast'); if(o)o.remove(); const d=document.createElement('div'); d.className='toast'+(err==='lock'?' lock':err?' err':''); d.textContent=m; if(err==='lock') d.insertAdjacentHTML('afterbegin','<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>'); document.body.appendChild(d); setTimeout(()=>d.remove(),err?4200:2400); }
async function guard(fn){ if(S.busy)return; S.busy=true; try{ await fn(); }catch(e){ toast(e.message==='OFFLINE'?'No connection. Try again.':e.message,true); } finally{ S.busy=false; } }

