// ---------- sync ----------
let pollT=null, syncing=false;
function startPoll(){ stopPoll(); pollT=setInterval(()=>{ if(!document.hidden) sync(); },2500); }
function stopPoll(){ if(pollT) clearInterval(pollT); pollT=null; }
document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&S.cid&&S.token) sync(); });
async function sync(first){
  if(syncing||!S.cid||!S.token) return; syncing=true;
  try{
    const r=await call('as_sync',{p_campaign:S.cid,p_after:S.lastId,p_rev:S.rev});
    S.role=r.role; let changed=false, newMsgs=r.messages||[];
    if(newMsgs.length){ S.msgs=S.msgs.concat(newMsgs); if(S.msgs.length>600) S.msgs=S.msgs.slice(-600); S.lastId=newMsgs[newMsgs.length-1].id; }
    if(r.campaign){ S.campaign=r.campaign; S.members=r.members; S.chars=r.characters; changed=true; useRules(); }
    S.rev=r.rev; S.offline=false;
    if(!first){ if(newMsgs.length) onMessages(newMsgs); if(changed) onState(); }
    if(changed){ fetchPics(); fetchUserPics(); }
  }catch(e){ if(first) throw e; S.offline=true; }
  finally{ syncing=false; }
}
