function drawTab(){ const v=$('#view'); if(!v) return; v.className='view'+(isFeed()?' feedwrap':''); ({play:viewPlay,chat:viewChat,sheet:viewSheets,tracker:viewTrackerTab,codex:viewCodex,more:viewMore,lchar:liteChar,lnotes:liteNotes,llore:liteLore})[S.tab](v); }
const sessionOpen=()=>!!((st('session')||{}).open);
