function drawBanner(){ const el=$('#banner'); if(!el||!S.campaign) return; const q=S.campaign.dm_req, ses=st('session')||{}, n=ses.n||0, can=canSession(); const starter=(theDM()||S.members.find(m=>m.id===S.campaign.owner)||{}).name||'the owner';
  el.innerHTML=`<div class="sesbar ${ses.open?'live':''}"><div class="grow"><b>${ses.open?'Session '+n:'Game paused'}</b><small>${ses.open?'In progress':(can?'':'Waiting for '+esc(starter))}</small></div>${n||ses.open?`<button class="btn sm ghost" data-act="catchup">Catch up${unseenRecap()?' •':''}</button>`:''}${can?(ses.open?'<button class="btn sm sec" data-act="wrapsession">Wrap up</button>':`<button class="btn sm" data-act="beginsession">Begin session ${n+1}</button>`):''}</div>`
   +((q&&q.user!==S.user.id&&!q.voted)?`<div class="warn" style="margin:8px 12px 0"><b>${esc(q.name)}</b> asks to be the Dungeon Master.<div class="row" style="margin-top:8px"><button class="btn sm" data-act="votedm" data-v="1">Approve</button><button class="btn sm sec" data-act="votedm" data-v="0">Decline</button></div></div>`:''); }
const theDM=()=>S.members.find(m=>m.role==='dm');
