function cue(html){ $('#fx').innerHTML=`<div class="cue" data-act="dxclose">${html}</div>`; }
function fxWatch(){ if(!S.campaign) return; const kn=known(), on=!!((st('combat')||{}).on);
  if(S._kn){ const fresh=kn.filter(x=>!S._kn.includes(x)); if(fresh.length&&!isDM()&&!$('#fx').firstChild){ sfx('drum'); cue(`<div class="cue-card"><div class="cue-eye">You encounter</div><div class="cue-art">${pi('skull',84,1.2)}</div><div class="cue-n">${esc(fresh.join(', '))}</div><div class="cue-s">Something new steps out of the dark.</div><div class="two"><button class="btn sec" data-act="cuelore" data-n="${esc(fresh[0])}">Read in Lore</button><button class="btn" data-act="dxclose">Ready</button></div></div>`); } }
  if(S._cb===false&&on&&!$('#fx').firstChild){ sfx('drum'); const foes=((st('combat')||{}).list||[]).filter(x=>x.side!=='party').slice(0,6); cue(`${pi('sword',44,1.4)}<div class="cue-eye" style="margin-top:14px">Round 1</div><h1 class="cue-big">Combat begins</h1><span class="cue-line"></span>${foes.length?`<div class="cue-foes">${foes.map(x=>`<div>${esc(x.name)}</div>`).join('')}</div>`:''}<button class="btn" data-act="dxclose">Ready</button>`); }
  S._kn=kn.slice(); S._cb=on; }
function onState(){ fxWatch(); drawDots(); drawClockLine(); drawBanner(); sndSync(); drawHud(); if($('#modal').firstChild) return; const ae=document.activeElement; if(ae&&$('#view')&&$('#view').contains(ae)&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName)) return; if(!isFeed()){ const v=$('#view'); const y=v?v.scrollTop:0; drawTab(); if(v) v.scrollTop=y; } }
function onMessages(n){ n.forEach(m=>{ if(m.k==='event'&&m.b.fix){ const o=S.msgs.find(x=>x.id===m.b.fix.id); if(o){ o.b=m.b.fix.body; const el=document.querySelector(`[data-mid="${o.id}"]`); if(el) el.outerHTML=msgHTML(o); } } }); if(isFeed()) appendFeed(n); drawPlayLog(); drawDots(); if(n.some(m=>m.k==='roll')) sfx('dice'); n.forEach(m=>{ if(m.k!=='event') return; const t=m.b.text; if(/began session|wrapped up session/.test(t)) sfx('gong'); else if(/started a combat|party faces/.test(t)) sfx('drum'); else if(/is now a level/.test(t)) sfx('chime'); }); }
function drawDots(){ const lo=$('#dot_codex'); if(lo&&S.campaign) lo.hidden=isDM()||!known().some(n=>!seenMon().includes(n)); const d=$('#dot_chat'); if(!d) return; const last=S.msgs.filter(m=>m.k==='chat').slice(-1)[0]; if(S.tab==='chat'&&last){ S.seen[S.cid+'chat']=last.id; LS.set('seen',S.seen); } d.hidden=!(last&&last.u!==S.user.id&&(S.seen[S.cid+'chat']||0)<last.id); }
function clockParts(t){ t=t||0; const T=R.T; const day=Math.floor(t/T.day)+1, rem=t%T.day, hour=Math.floor(rem/T.hour), min=Math.floor((rem%T.hour)*60/T.hour), turn=Math.floor(t/T.turn), round=Math.floor((t%T.turn)/T.round)+1, seg=(t%T.round)+1; return {day,hour,min,turn,round,seg,label:`Day ${day} · ${String(hour).padStart(2,'0')}:${String(min).padStart(2,'0')}`}; }
