  const fire=(g)=>{ bed(SND.brown,'lowpass',260,0.5,g*0.9,0.05); every(60,380,()=>noiseHit('highpass',rnd(1800,5000),0.7,rnd(0.012,0.05),rnd(0.02,0.09)*g*4,0.1,rnd(-0.5,0.5))); every(1500,5000,()=>noiseHit('bandpass',rnd(500,900),1,0.09,0.12*g*4,0.2)); };
