     dungeon(){ bed(SND.brown,'lowpass',300,0.4,0.2,0.1); drops(3500,9000,0.07); every(11000,24000,()=>thud(rnd(60,90),0.5,0.16,0.9)); every(300,1200,()=>noiseHit('highpass',rnd(2500,5000),0.7,0.02,0.012,0.2,0.6)); },
