  const lfo=x.createOscillator(), lg=x.createGain(); lfo.frequency.value=0.07; lg.gain.value=60; lfo.connect(lg); lg.connect(lp.frequency); lfo.start(); nodes.push(lfo);
  const thud=(g,when)=>{ const t=x.currentTime+when, o=x.createOscillator(), gn=x.createGain(); o.frequency.setValueAtTime(62,t); o.frequency.exponentialRampToValueAtTime(34,t+0.2); gn.gain.setValueAtTime(0.0001,t); gn.gain.exponentialRampToValueAtTime(g,t+0.012); gn.gain.exponentialRampToValueAtTime(0.0001,t+0.24); o.connect(gn); gn.connect(out); o.start(t); o.stop(t+0.3); };
  const beat=()=>{ if(!alive) return; if(!document.hidden){ thud(lv===2?0.55:0.38,0); thud(lv===2?0.4:0.26,0.19); } timers.push(setTimeout(beat,lv===2?760:1150)); }; beat();
  const swell=()=>{ if(!alive) return; if(!document.hidden){ const t=x.currentTime, base=lv===2?rnd(1100,1500):rnd(500,700); [1,1.059].forEach(m=>{ const o=x.createOscillator(), gn=x.createGain(); o.type='sine'; o.frequency.setValueAtTime(base*m,t); o.frequency.linearRampToValueAtTime(base*m*(lv===2?1.04:0.98),t+5); gn.gain.setValueAtTime(0.0001,t); gn.gain.exponentialRampToValueAtTime(lv===2?0.014:0.008,t+2.2); gn.gain.exponentialRampToValueAtTime(0.0001,t+5); o.connect(gn); gn.connect(out); o.start(t); o.stop(t+5.2); }); } timers.push(setTimeout(swell,lv===2?rnd(7000,13000):rnd(14000,26000))); }; timers.push(setTimeout(swell,rnd(2000,5000)));
