function drawTense(){ const b=$('#tensebtn'); if(b){ const lv=tenseLv(); b.className='sndbtn tns'+(lv?' t'+lv:''); b.hidden=!(running()&&sessionOpen()); } }
function curScene(){ return sessionOpen()?(((st('scene')||{}).id)||'cave'):'cave'; }
function sndUnlock(){ try{ if(navigator.audioSession) navigator.audioSession.type='playback'; }catch(e){} if(!SND.el){ const n=4000, hdr=new Uint8Array(44+n), dv=new DataView(hdr.buffer); 'RIFF'.split('').forEach((c,i)=>hdr[i]=c.charCodeAt(0)); dv.setUint32(4,36+n,true); 'WAVEfmt '.split('').forEach((c,i)=>hdr[8+i]=c.charCodeAt(0)); dv.setUint32(16,16,true); dv.setUint16(20,1,true); dv.setUint16(22,1,true); dv.setUint32(24,8000,true); dv.setUint32(28,8000,true); dv.setUint16(32,1,true); dv.setUint16(34,8,true); 'data'.split('').forEach((c,i)=>hdr[36+i]=c.charCodeAt(0)); dv.setUint32(40,n,true); hdr.fill(128,44); let bin=''; hdr.forEach(b=>bin+=String.fromCharCode(b)); const a=SND.el=document.createElement('audio'); a.loop=true; a.setAttribute('playsinline',''); a.src='data:audio/wav;base64,'+btoa(bin); } const pr=SND.el.play(); if(pr&&pr.catch) pr.catch(()=>{}); }
function sndSync(){ drawTense(); const want=(SND.on&&S.campaign)?curScene():'silence'; if(!SND.ctx){ return; } const tl=(SND.on&&S.campaign)?tenseLv():0; if(tl!==(SND.tlv||0)){ if(SND.tns) SND.tns.stop(); SND.tns=tl?sndTense(tl):null; SND.tlv=tl; } if(want===SND.curId) return; if(SND.cur) SND.cur.stop(); SND.cur=null; SND.curId=want; if(want!=='silence') SND.cur=sndScene(want); }
function sfx(kind){ if(!SND.on||!SND.ctx) return; const x=SND.ctx, t=x.currentTime; const hit=(f,f2,dur,g,type,when)=>{ const o=x.createOscillator(); o.type=type||'sine'; o.frequency.setValueAtTime(f,t+when); o.frequency.exponentialRampToValueAtTime(f2,t+when+dur); const gn=x.createGain(); gn.gain.setValueAtTime(g,t+when); gn.gain.exponentialRampToValueAtTime(0.0001,t+when+dur); o.connect(gn); gn.connect(SND.master); o.start(t+when); o.stop(t+when+dur+0.05); };
  const click=(when,g)=>{ const s=x.createBufferSource(); s.buffer=SND.white; const bq=x.createBiquadFilter(); bq.type='bandpass'; bq.frequency.value=2200+Math.random()*2500; bq.Q.value=4; const gn=x.createGain(); gn.gain.setValueAtTime(g,t+when); gn.gain.exponentialRampToValueAtTime(0.0001,t+when+0.05); s.connect(bq); bq.connect(gn); gn.connect(SND.master); s.start(t+when,Math.random()); s.stop(t+when+0.08); };
  if(kind==='dice'){ let w=0; for(let i=0;i<7;i++){ click(w,0.22-i*0.02); w+=0.03+Math.random()*0.07; } }
  else if(kind==='gong'){ [[110,2.8,0.35],[164.8,2.2,0.2],[221,1.8,0.14],[331,1.2,0.07]].forEach(([f,d,g])=>hit(f,f*0.995,d,g,'sine',0)); click(0,0.25); }
  else if(kind==='drum'){ hit(100,40,0.35,0.7,'sine',0); hit(90,38,0.3,0.5,'sine',0.22); }
  else if(kind==='flip'){ click(0,0.25); hit(700,300,0.08,0.08,'triangle',0.01); }
  else if(kind==='chime'){ [523,784].forEach((f,i)=>hit(f,f,0.7,0.05,'sine',i*0.12)); } }
function sndToggle(){ SND.on=!SND.on; LS.set('snd',SND.on); if(SND.on){ if(!sndInit()){ SND.on=false; LS.set('snd',false); return toast('This browser cannot play sound',true); } sndUnlock(); SND.ctx.resume(); sfx('chime'); } else if(SND.el){ SND.el.pause(); } SND.curId=SND.on?SND.curId:SND.curId; sndSync(); const b=$('#sndbtn'); if(b) b.classList.toggle('on',SND.on); if(S.tab==='more'||S.tab==='tracker') drawTab(); toast(SND.on?'Sound on: '+(SCENES.find(x=>x[0]===curScene())||SCENES[0])[1].toLowerCase():'Sound off'); }
const sndWake=()=>{ if(!SND.on) return; if(!SND.ctx){ if(sndInit()){ sndUnlock(); SND.ctx.resume(); sndSync(); } } else if(SND.ctx.state!=='running'){ sndUnlock(); SND.ctx.resume(); } };
['pointerup','touchend','click'].forEach(ev=>document.addEventListener(ev,sndWake,{passive:true}));
document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&SND.on&&SND.ctx) SND.ctx.resume(); });
const SPK='<svg viewBox="0 0 24 24"><path d="M4 9.500h4l5-4v13l-5-4H4z"/><path d="M16.500 9a4 4 0 010 6M19 6.500a8 8 0 010 11"/></svg>';
// ---------- hero card ----------
function heroCard(id){ const c=CH().find(x=>x.id===id); if(!c) return; const d=c.data, k0=d.classes[0], C=k0&&R.classes[k0.id]; const col=({dwarf:'#8a4a1a',elf:'#1f6a4a',halfling:'#7a5a1a'})[(k0||{}).id]||{fighter:'#6a1d1e',cleric:'#7a5a12',magicuser:'#1f3f66',thief:'#2f4a2a',monk:'#4a2a55'}[(C||{}).group]||'#6a1d1e';
  const p=S.pics[c.id], pic=(d.pv&&p&&p.pv===d.pv&&p.data)?`<img src="${esc(p.data)}" alt="">`:esc(initials(d.name)); const svs=R.savesFor?R.savesFor(d):null; const mem=(d.mem||[]).filter(m=>!m.cast).map(m=>m.n);
  const nx=k0?nextXp(k0,d):null, cur0=k0?(R.xpFor(k0.id,k0.level)||0):0;
  $('#modal').innerHTML=`<div class="hc-bg" data-act="hcclose"><div class="hc" id="hc" style="--hc:${col}">
   <div class="hc-face hc-front"><div class="hc-top"><span>${k0?'Level '+d.classes.map(k=>k.level).join('/'):''}</span><span>${esc(d.classes.map(k=>R.classes[k.id].name).join(' / ')||'Adventurer')}</span></div>
    <div class="hc-port">${pic}</div><div class="hc-name">${esc(d.name||'Unnamed')}</div>
    <div class="hc-sub">${esc(k0?R.titleFor(k0.id,k0.level):'')}${d.align?', '+esc(d.align.toLowerCase()):''}${d.dead?' (fallen)':''}</div>
    <div class="hc-stats"><div><b>${d.hp}/${d.hpMax}</b><span>Hit points</span></div><div><b>${calcAC(d)}</b><span>Armor class</span></div><div><b>${k0?k0.xp.toLocaleString():0}</b><span>Experience</span></div></div>
    <div class="hc-hp"><i style="width:${d.hpMax?Math.max(0,Math.min(100,100*d.hp/d.hpMax)):0}%"></i></div>
    <div class="hc-ab">${R.abilities.map(a=>`<div><b>${d.ab[a]}</b><span>${a}</span></div>`).join('')}</div>
    <div class="hc-foot"><span>Played by ${esc(memberName(c.user_id))}</span><span>${nx!=null?Math.max(0,nx-k0.xp).toLocaleString()+' to level '+(k0.level+1):''}</span></div><div class="hc-shine"></div></div>
   <div class="hc-face hc-back"><h3>${esc(d.name||'Unnamed')}</h3><div class="sc">
    ${svs?svs.slice(0,5).map(r=>`<div class="kv"><span>Save: ${esc(r[0].toLowerCase())}</span><span>${esc(r[1])}</span></div>`).join(''):''}
    ${(d.weapons||[]).slice(0,4).map(w=>{ const inf=weaponInfo(w.n); return `<div class="kv"><span>${esc(w.n)}</span><span>${inf.d?esc(inf.d.sm):''}</span></div>`; }).join('')}
    <div class="kv"><span>Armor</span><span>${esc(d.armor)}${d.shield&&d.shield!=='None'?' and shield':''}</span></div>
    ${mem.length?`<div class="kv"><span>Spells ready</span><span>${esc(mem.join(', '))}</span></div>`:''}
    <div class="kv"><span>Purse</span><span>${R.money(wealthCp(d))}</span></div>
    <div class="kv"><span>Carrying</span><span>${(d.items||[]).length} item${(d.items||[]).length===1?'':'s'}, ${R.encFor(carried(d),R.strength(d.ab.str,d.strPct)[2])[1].toLowerCase()}</span></div>
    <div class="kv"><span>Speaks</span><span>${esc((d.langs||[]).map(l=>l.replace(' (alignment)','')).join(', ')||'Common')}</span></div>
    ${d.notes?`<p class="small" style="white-space:pre-wrap;margin:8px 2px 0">${esc(d.notes.slice(0,240))}</p>`:''}</div></div>
  </div><div class="hc-hint">Tap the card to turn it over. Drag to tilt it in the light.</div><div class="row"><button class="btn sm sec" data-act="hcsheet" data-id="${c.id}">Open the sheet</button><button class="btn sm sec" data-act="close">Close</button></div></div>`;
  const el=$('#hc'); let down=null, moved=false, flip=0; const set=(k,v)=>el.style.setProperty(k,v);
  el.addEventListener('pointerdown',e=>{ down=[e.clientX,e.clientY]; moved=false; el.classList.add('drag'); try{ el.setPointerCapture(e.pointerId); }catch(x){} });
  el.addEventListener('pointermove',e=>{ if(!down&&e.pointerType!=='mouse') return; const r=el.getBoundingClientRect(), px=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)), py=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)); if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])>7) moved=true; set('--ry',((px-0.5)*30)+'deg'); set('--rx',((0.5-py)*24)+'deg'); set('--mx',(px*100)+'%'); set('--my',(py*100)+'%'); set('--sh','0.9'); });
  const up=()=>{ el.classList.remove('drag'); if(down&&!moved){ flip=flip?0:180; set('--flip',flip+'deg'); sfx('flip'); } down=null; set('--rx','0deg'); set('--ry','0deg'); set('--sh','0.55'); };
  el.addEventListener('pointerup',up); el.addEventListener('pointercancel',()=>{ down=null; el.classList.remove('drag'); }); el.addEventListener('pointerleave',()=>{ if(!down){ set('--rx','0deg'); set('--ry','0deg'); } }); }
