const DIESHAPE={4:'50,6 96,90 4,90',6:'12,12 88,12 88,88 12,88',8:'50,4 94,50 50,96 6,50',10:'50,4 92,40 74,92 26,92 8,40',12:'50,4 90,22 98,64 68,96 32,96 2,64 10,22',20:'50,3 92,26 92,74 50,97 8,74 8,26'};
function dieSVG(sides,val,theme){ const t=THEMES[theme]||THEMES.gold, pts=DIESHAPE[sides]||DIESHAPE[20]; return `<svg viewBox="0 0 100 100"><defs><linearGradient id="dg_${theme}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${t[1]}"/><stop offset="1" stop-color="${t[2]}"/></linearGradient></defs><polygon points="${pts}" fill="url(#dg_${theme})" stroke="${t[1]}" stroke-width="3" stroke-linejoin="round"/><polygon points="${pts}" fill="none" stroke="#0006" stroke-width="1" transform="translate(50 50) scale(.72) translate(-50 -50)"/><text x="50" y="${sides===4?70:62}" text-anchor="middle" font-family="Cinzel,Georgia,serif" font-weight="900" font-size="${String(val).length>2?26:34}" fill="${t[3]}" class="dv">${val}</text></svg>`; }
function verdict(b){ const one=b.sets&&b.sets.length===1; if(!one) return null; const tot=b.sets[0].total, raw=b.sets[0].dice.reduce((a,c)=>a+c,0);
  if(b.kind==='attack'&&b.cmp==='ge'&&b.target!=null) return tot>=b.target?['Hits '+(b.foe||'the target'),true]:['Misses '+(b.foe||'the target'),false];
  if(b.cmp==='ge'&&b.target!=null) return tot>=b.target?['Success',true]:['Failed',false];
  if(b.cmp==='le'&&b.target!=null) return raw<=b.target?['Success',true]:['Failed',false];
  if(b.kind==='attack'&&b.thac!=null){ const ac=b.thac-tot; return tot<b.thac-9?['Misses even armor class 9',false]:['Hits armor class '+Math.max(-3,ac)+(ac>-3?' or worse':''),true]; }
  return null; }
function diceShow(b,then){ const fx=$('#fx'), theme=THEMES[b.theme]?b.theme:S.dtheme, set=b.sets[0], show=set.dice.length<=6?set.dice:[set.total-(b.mod||0)], v=verdict(b), nat=(b.s===20&&b.n===1)?set.dice[0]:0;
  fx.innerHTML=`<div class="dx" data-act="dxclose"><span class="dx-rays" aria-hidden="true"></span><div class="dx-plate">${pi(b.kind==='attack'?'sword':'dice',18)}<span>${esc(b.label||'Dice roll')}</span></div><div class="dx-row">${show.map((d,i)=>`<div class="dx-die" style="animation-delay:${i*70}ms">${dieSVG(set.dice.length<=6?b.s:20,'?',theme)}</div>`).join('')}</div><div class="dx-sum" id="dx_tot"></div><div id="dx_v" style="width:100%"></div><div class="dx-btns" id="dx_b"></div></div>`;
  sfx('dice'); try{ navigator.vibrate&&navigator.vibrate([20,40,20,40,30]); }catch(e){}
  const texts=[...fx.querySelectorAll('.dv')]; const iv=setInterval(()=>texts.forEach(t=>t.textContent=1+Math.floor(Math.random()*b.s)),70);
  const land=()=>{ clearInterval(iv); if(!fx.firstChild) return; texts.forEach((t,i)=>t.textContent=show[i]); const dx=fx.firstChild; dx.classList.add('landed'); if(nat===20) dx.classList.add('crit'); if(nat===1) dx.classList.add('fumble');
    const raw=set.dice.reduce((a,c)=>a+c,0);
    $('#dx_tot').innerHTML=(b.mod?`<div class="dx-chip"><b>${raw}</b><small>${b.n}d${b.s}${b.manual?' · table':''}</small></div><span>${b.mod>0?'+':'−'}</span><div class="dx-chip"><b>${Math.abs(b.mod)}</b><small>adjust</small></div><span>=</span>`:(b.manual?'<div class="dx-chip"><b>'+raw+'</b><small>table dice</small></div><span>=</span>':''))+`<div class="dx-total">${set.total}</div>`;
    const good=nat===20||(v&&v[1]), bad=nat===1||(v&&!v[1]); const word=nat===20?'NATURAL 20':nat===1?'NATURAL 1':v?(b.kind==='attack'?(v[1]?'HIT':'MISS'):(v[1]?'SUCCESS':'FAILED')):'';
    $('#dx_v').innerHTML=word?`<div class="dx-ban ${good&&!bad?'good':bad?'bad':'good'}"><b>${word}</b>${v?`<small>${esc(v[0])}</small>`:''}</div>`:'';
    const t=THEMES[theme]; const burst=(nat===20||(v&&v[1]))?26:(v&&!v[1])?0:12; let ps=''; for(let i=0;i<burst;i++){ const a=Math.random()*6.283, r=70+Math.random()*130; ps+=`<i class="dx-p" style="--x:${Math.cos(a)*r}px;--y:${Math.sin(a)*r}px;background:${i%3===0?'#7ef0c0':i%3===1?t[1]:'#ffd27a'};animation-delay:${Math.random()*80}ms"></i>`; } dx.querySelector('.dx-row').insertAdjacentHTML('beforeend',ps);
    if(nat===20) sfx('chime'); else if(nat===1||(v&&!v[1])) sfx('drum'); try{ navigator.vibrate&&navigator.vibrate(nat===20?[60,40,120]:40); }catch(e){}
    const extra=then?then(b):'';
    $('#dx_b').innerHTML=(extra||'')+`<div class="two"><button class="btn sec" data-act="dxclose">Done</button>${b.id&&b.sets.length===1?`<button class="btn ghost" data-act="fixroll" data-id="${b.id}">Wrong number? Fix it</button>`:'<span></span>'}</div>`;
    if(!extra) setTimeout(()=>{ if(fx.firstChild===dx) fx.innerHTML=''; },5200); };
  setTimeout(land,document.hidden?0:950); }
function parseDice(s){ s=String(s); let m=s.match(/^(\d+)d(\d+)$/); if(m) return [+m[1],+m[2],0]; m=s.match(/^(\d+)-(\d+)$/); if(m){ const a=+m[1],b=+m[2]; return b%a===0?[a,b/a,0]:[1,b-a+1,a-1]; } return [1,6,0]; }
// spec: {label,n,s,mod,ch,meta,help,then}
let RS=null;
function askRoll(spec){ RS=Object.assign({n:1,s:20,mod:0,ch:'table',way:LS.get('rway','app'),pick:null},spec); drawRoll(); }
function drawRoll(){ const sp=RS, th=THEMES[S.dtheme]||THEMES.gold, m=sp.meta||{}, grid=sp.n===1&&sp.s<=20, each=sp.n<=8;
  const need=m.foe&&m.target!=null?'':m.kind==='attack'&&m.thac!=null?`<div class="rp-lab">Total you need to hit<em>${sp.mod?'Adjustment already added':''}</em></div><div class="need">${[9,7,5,4,3,2].map(a=>`<div><small>AC ${a}</small><b>${Math.max(2,Math.min(20,m.thac-a))}</b></div>`).join('')}</div>`:(m.target!=null?`<div class="rp-lab">What you need<em>${m.cmp==='le'?m.target+' or less':m.target+' or more'}</em></div>`:'');
  const tot=sp.pick!=null?sp.pick+(sp.mod||0):null;
  modal(sp.title||'Roll',`<div class="rp-top">${dieSVG(sp.s,sp.n>1?sp.n+'×':'d'+(sp.s===100?'%':sp.s),S.dtheme)}<div class="grow"><div class="rp-t">${esc(sp.label||'Dice roll')}</div><div class="rp-f"><span class="chip">${sp.n}d${sp.s===100?'%':sp.s}</span>${sp.mod?`<span>${sp.mod>0?'+':'−'}</span><span class="chip">${Math.abs(sp.mod)} adjustment</span>`:''}</div></div></div>
   ${sp.help?`<div class="small mute" style="margin-top:10px">${esc(sp.help)}</div>`:''}${need}
   <div class="rp-lab">Your dice<em style="color:var(--amber)">${th[0]}</em></div><div class="gems">${Object.keys(THEMES).map(k=>`<button class="gem ${S.dtheme===k?'on':''}" data-act="dtheme" data-k="${k}" aria-label="${THEMES[k][0]} dice" aria-pressed="${S.dtheme===k}"><i style="background:linear-gradient(140deg,${THEMES[k][1]},${THEMES[k][2]})"></i></button>`).join('')}</div>
   <div class="ways"><button class="way ${sp.way==='app'?'on':''}" data-act="rway" data-w="app" aria-pressed="${sp.way==='app'}">${pi('dice',24)}<span><b>Roll here</b><small>The app rolls</small></span></button><button class="way ${sp.way==='real'?'on':''}" data-act="rway" data-w="real" aria-pressed="${sp.way==='real'}">${pi('target',24)}<span><b>Real dice</b><small>${grid?'Tap what it showed':'Enter what they showed'}</small></span></button></div>
   ${sp.way==='real'?(grid?`<div class="nums">${Array.from({length:sp.s},(_,i)=>i+1).map(n=>`<button class="${sp.pick===n?'on':n===1?'lo':n===sp.s?'hi':''}" data-act="rnum" data-n="${n}" aria-pressed="${sp.pick===n}">${n}</button>`).join('')}</div>`:`<label>${each?'What each die showed':'Total on the dice, before any adjustment'}</label><div class="row wrap">${each?Array.from({length:sp.n},(_,i)=>`<input inputmode="numeric" data-man="${i}" placeholder="1-${sp.s}" aria-label="Die ${i+1}" style="width:76px;text-align:center">`).join(''):'<input inputmode="numeric" data-man="t" aria-label="Total" style="width:120px;text-align:center">'}</div>`):''}
   <div style="height:14px"></div>${sp.way==='real'?`<button class="btn block" data-act="rollman2" style="min-height:52px;font-size:16px" ${grid&&sp.pick==null?'disabled':''}>${grid?(sp.pick==null?'Tap the number you rolled':`Record ${sp.pick}${sp.mod?' · total '+tot:''}`):'Record it'}</button>`:`<button class="btn block" data-act="rollapp" style="min-height:52px;font-size:16px">${pi('dice',18)} Roll ${sp.n}d${sp.s===100?'%':sp.s}${sp.mod?(sp.mod>0?' + ':' − ')+Math.abs(sp.mod):''}</button>`}`); }
async function execRoll(manual){ const sp=RS; const meta=Object.assign({theme:S.dtheme},sp.meta||{}); const r=await roll({n:sp.n,s:sp.s,mod:sp.mod,label:sp.label,channel:sp.ch,meta,manual:manual||null}); closeModal(); diceShow(r,sp.then); if(sp.after) sp.after(r); return r; }
function fixRollModal(m){ const b=m.b, d=b.sets[0].dice; modal('Correct this roll',`<div style="font:700 17px var(--sans)">${esc(b.label||'Dice roll')}</div><div class="small mute">Recorded as ${b.sets[0].total}. Enter what the dice really showed.</div><div class="row wrap" style="margin-top:12px">${d.map((v,i)=>`<input inputmode="numeric" data-fix="${i}" value="${v}" style="width:70px;text-align:center">`).join('')}</div><div class="small mute" style="margin-top:8px">The log keeps a note of the correction. If the wrong number changed hit points or anything else, fix those on the sheet: the sheet's History can put it back.</div><div style="height:14px"></div><button class="btn block" data-act="fixroll2" data-id="${m.id}">Save the correction</button>`); }
