function hashStr(s){ let h=2166136261; for(const c of String(s)) h=Math.imul(h^c.charCodeAt(0),16777619)>>>0; return h; }
function letters(seed,name){ const h=hashStr(seed), G=[['#ef4b5b','#7a1220'],['#5b8ff0','#1c3a80'],['#5fe0a0','#14704a'],['#f0c868','#8f6418'],['#b79cff','#4a2a8a'],['#ff9a5a','#8a3a12'],['#5fd6e0','#14606a']], g=G[h%G.length], g2=G[(h>>>4)%G.length], ang=(h>>>8)%360, pat=(h>>>12)%3;
  const bg=pat===0?`linear-gradient(${ang}deg,${g[0]},${g[1]})`:pat===1?`conic-gradient(from ${ang}deg,${g[1]},${g[0]},${g2[1]},${g[1]})`:`radial-gradient(circle at ${20+(h>>>16)%60}% ${20+(h>>>20)%60}%,${g[0]},${g[1]} 70%)`; return `<span class="lt" style="background:${bg}">${esc(initials(name))}</span>`; }
