function diffNote(a,b){ const o=[]; if(a.name!==b.name) o.push(`Renamed from ${a.name||'unnamed'} to ${b.name}`); if(a.hp!==b.hp) o.push(`Hit points ${a.hp} → ${b.hp}`); if(a.hpMax!==b.hpMax) o.push(`Maximum hit points ${a.hpMax} → ${b.hpMax}`);
  (b.classes||[]).forEach(k=>{ const p=(a.classes||[]).find(x=>x.id===k.id); const nm=R.classes[k.id]?R.classes[k.id].name:k.id; if(!p){ o.push(`Class set to ${nm}`); return; } if(p.level!==k.level) o.push(`${nm} level ${p.level} → ${k.level}`); if(p.xp!==k.xp) o.push(`${nm} x.p. ${p.xp.toLocaleString()} → ${k.xp.toLocaleString()}`); });
  R.abilities.forEach(k=>{ if((a.ab||{})[k]!==(b.ab||{})[k]) o.push(`${R.abilityNames[k]} ${(a.ab||{})[k]} → ${b.ab[k]}`); });
  if(a.align!==b.align) o.push(`Alignment: ${b.align}`); if(a.armor!==b.armor||a.shield!==b.shield) o.push(`Armor: ${b.armor}${b.shield&&b.shield!=='None'?' + shield':''}`); if((a.acMod||0)!==(b.acMod||0)) o.push(`Magic AC bonus ${a.acMod||0} → ${b.acMod||0}`);
  const wa=wealthCp(a), wb=wealthCp(b); if(wa!==wb) o.push(`Money ${R.money(wa)} → ${R.money(wb)}`);
  const cnt=l=>{ const m={}; (l||[]).forEach(i=>m[i.n]=(m[i.n]||0)+(+i.qty||1)); return m; }; const ia=cnt(a.items), ib=cnt(b.items); Object.keys(ib).forEach(n=>{ if(!ia[n]) o.push(`Added ${n}`); else if(ia[n]!==ib[n]) o.push(`${n} ×${ia[n]} → ×${ib[n]}`); }); Object.keys(ia).forEach(n=>{ if(!ib[n]) o.push(`Removed ${n}`); });
  const wn=l=>(l||[]).map(w=>w.n); wn(b.weapons).forEach(n=>{ if(!wn(a.weapons).includes(n)) o.push(`Weapon added: ${n}`); }); wn(a.weapons).forEach(n=>{ if(!wn(b.weapons).includes(n)) o.push(`Weapon removed: ${n}`); });
  const ma=(a.mem||[]), mb=(b.mem||[]); if(mb.length>ma.length) o.push(`Memorized ${mb[mb.length-1].n}`); else if(mb.length<ma.length) o.push('Cleared memorized spells'); else mb.forEach((m,i)=>{ if(ma[i]&&ma[i].cast!==m.cast) o.push(m.cast?`Cast ${m.n}`:`Recovered ${m.n}`); });
  if(JSON.stringify(a.known||{})!==JSON.stringify(b.known||{})) o.push('Spell book changed'); if((a.langs||[]).join()!==(b.langs||[]).join()) o.push('Languages changed'); if((a.notes||'')!==(b.notes||'')) o.push('Notes changed'); if(!!a.dead!==!!b.dead) o.push(b.dead?'Marked dead':'Marked alive'); const ca=a.cond||[], cb=b.cond||[]; cb.forEach(x=>{ if(!ca.includes(x)) o.push('Now '+((CONDS.find(c=>c[0]===x)||[0,x])[1]).toLowerCase()); }); ca.forEach(x=>{ if(!cb.includes(x)) o.push('No longer '+((CONDS.find(c=>c[0]===x)||[0,x])[1]).toLowerCase()); });
  return (o.join('; ')||'Edited the sheet').slice(0,290); }
