  memorize(el){ const d=cur().data, L=el.dataset.list, lvl=+el.dataset.lvl; const book=['magicuser','illusionist'].includes(L); const list=book?((d.known||{})[L]||[]).filter(s=>s.lvl===lvl).map(s=>s.n):R.spells[L][lvl-1]; if(!list.length) return toast('No level '+lvl+' spells in the spell book yet. Add them under Spell book.',true); modal(`Memorize a level ${lvl} spell`,list.map(n=>{ const inf=((R.spellInfo||{})[L]||{})[n]; return `<button class="btn sec block" style="margin-bottom:6px;justify-content:flex-start;text-align:left;flex-direction:column;align-items:flex-start" data-act="mem2" data-list="${L}" data-lvl="${lvl}" data-n="${esc(n)}"><span>${esc(n)}</span>${inf?`<span class="small mute" style="font-weight:400">Range ${esc(inf[0])} · ${esc(inf[1])}<br>${esc(inf[2])}</span>`:''}</button>`; }).join('')); },
