  restspells(){ modal('A new day',`<p>After a full rest, spells can be memorized again (about 15 minutes per spell level).</p><button class="btn block" data-act="rest2" data-m="keep">Re-memorize the same spells</button><div style="height:8px"></div><button class="btn sec block" data-act="rest2" data-m="clear">Clear all and choose again</button>`); },
