  noteadd(){ const t=($('#nt_text')||{}).value||'', po=!!($('#nt_po')||{}).checked; if(!t.trim()) return toast('Write something first',true); guard(async()=>{ await call('as_note_save',{p_campaign:S.cid,p_id:null,p_text:t,p_private:po}); S.noteDraft=''; S.notePo=false; await loadNotes(true); toast(po?'Saved. The DM can’t see it.':'Note saved'); }); },
