  addlight(el){ const who=(el&&el.dataset&&el.dataset.who)||(playChar()||myChars()[0]||{data:{name:''}}).data.name; formModal('Light a source',[{id:'type',label:'What are you lighting?',type:'select',options:Object.keys(R.lights),value:'Torch'},{id:'who',label:'Carried by',value:who}],async f=>{ const L=R.lights[f.type]; const tn=now(); const ls=(st('lights')||[]).filter(l=>(l.end==null&&l.lit!==false&&l.left==null)||(l.lit===false?l.left:l.end-tn)>0); ls.push({name:f.type,type:f.type,who:f.who,lit:true,end:L[1]?now()+L[1]*R.T.turn:null}); await setState('lights',ls); logEvent(`: ${f.who||'someone'} lights a ${f.type.toLowerCase()}`); closeModal(); drawTab(); }); },
