  init(){ const c0=st('combat')||{}; if(c0.init) return toast('Initiative is already rolled for this round'); if(S._initBusy) return; S._initBusy=true; guard(async()=>{ try{ if(!c0.on){ const list=CH().filter(c=>!c.data.dead).map(c=>({name:c.data.name,side:'party',hp:c.data.hp,hpMax:c.data.hpMax,ac:calcAC(c.data),cid:c.id})); await setState('combat',{on:true,round:1,list}); await logEvent('started a combat'); } }finally{} const r=await roll({n:1,s:6,times:2,label:'Initiative (party, monsters)'}); const cb=Object.assign({},st('combat')); cb.init=[r.sets[0].total,r.sets[1].total]; await setState('combat',cb); S._initBusy=false; toast(cb.init[0]>cb.init[1]?'The party acts first':cb.init[0]<cb.init[1]?'The monsters act first':'Both sides act together'); }).finally(()=>{ S._initBusy=false; }); },
