  pitem(el){ const p=st('party')||{coins:{},items:[]}, i=+el.dataset.i, it=i>=0?p.items[i]:{n:'',qty:1,note:''}; formModal(i>=0?'Shared item':'Add shared item',[{id:'n',label:'Item',value:it.n},{id:'qty',label:'Quantity',num:true,value:it.qty},{id:'note',label:'Note (who carries it, what it does)',value:it.note||'',max:200}],async f=>{ if(!f.n.trim()) return; const n=JSON.parse(JSON.stringify(p)); n.items=n.items||[]; n.coins=n.coins||{}; const o={n:f.n.trim(),qty:Math.max(1,num(f.qty)),note:f.note}; if(i>=0) n.items[i]=o; else { n.items.push(o); logEvent(`: the party gains ${o.n}${o.qty>1?' ×'+o.qty:''}`); } await setState('party',n); closeModal(); },i>=0?`<button class="btn danger block" style="margin-top:8px" data-act="pitemdel" data-i="${i}">Remove</button>`:''); },
  pitemdel(el){ guard(async()=>{ const n=JSON.parse(JSON.stringify(st('party'))); n.items.splice(+el.dataset.i,1); await setState('party',n); closeModal(); }); },
