  award(){ const live=CH().filter(c=>!c.data.dead); modal('Award experience',`<label>Total x.p. to share</label><input id="aw_xp" inputmode="numeric" placeholder="1200" value="${foeXp()||''}">${foeXp()?`<div class="small mute" style="margin-top:4px">Filled in from defeated foes in the combat tracker: ${foeXp().toLocaleString()} x.p. Add treasure at 1 x.p. per g.p.</div>`:''}<label>Who shares it</label>${live.map(c=>`<label class="row" style="gap:10px;color:var(--text);font-size:15px"><input type="checkbox" data-aw="${c.id}" checked style="width:22px;min-height:22px">${esc(c.data.name)} <span class="mute small">${esc(classLine(c.data))}</span></label>`).join('')||'<div class="empty">No living characters.</div>'}<label>Reason (optional)</label><input id="aw_why" maxlength="80" placeholder="The goblin warren"><div style="height:14px"></div><button class="btn block" data-act="award2">Award</button>`); },
  award2(){ const total=num($('#aw_xp').value), ids=[...document.querySelectorAll('[data-aw]:checked')].map(e=>e.dataset.aw), why=$('#aw_why').value.trim(); if(!total||!ids.length) return toast('Enter an amount and pick at least one character',true); guard(async()=>{ const each=Math.floor(total/ids.length); for(const id of ids){ const c=JSON.parse(JSON.stringify(CH().find(x=>x.id===id))); grantXp(c.data,each); await call('as_save_character',{p_campaign:S.cid,p_id:id,p_data:c.data,p_note:'Awarded '+each.toLocaleString()+' x.p.'+(why?' for '+why:'')}); } await logEvent(`awarded ${total.toLocaleString()} x.p.${why?' for '+why:''} (${each.toLocaleString()} each to ${ids.length})`); await sync(); closeModal(); onState(); toast('Experience awarded'); }); },
