  rollman2(){ const sp=RS, ins=[...document.querySelectorAll('[data-man]')]; let dice; if(sp.pick!=null&&!ins.length) return guard(()=>execRoll([sp.pick])); if(ins[0].dataset.man==='t'){ const tot=parseInt(ins[0].value,10); if(!(tot>=sp.n&&tot<=sp.n*sp.s)) return toast(`Enter a total between ${sp.n} and ${sp.n*sp.s}`,true); dice=[]; let left=tot; for(let i=0;i<sp.n;i++){ const v=Math.max(1,Math.min(sp.s,left-(sp.n-1-i))); dice.push(v); left-=v; } } else { dice=ins.map(i=>parseInt(i.value,10)); if(dice.some(v=>!(v>=1&&v<=sp.s))) return toast(`Each die must be between 1 and ${sp.s}`,true); } guard(()=>execRoll(dice)); },
